import{_ as d,C as s,o as i,c as l,aj as a,E as r,j as e,a as n}from"./framework.js";const y=JSON.parse('{"title":"Cookie | Settings | Admin CMS","description":"Cookie Management configures the front-end Cookie consent banner: enable scope, display style, multilingual copy, Cookie categories, external resource classification, and consent…","frontmatter":{"title":"Cookie | Settings | Admin CMS","description":"Cookie Management configures the front-end Cookie consent banner: enable scope, display style, multilingual copy, Cookie categories, external resource classification, and consent…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/settings/cookie.html"}]]},"headers":[],"relativePath":"cms/settings/cookie.md","filePath":"en/cms/settings/cookie.md","lastUpdated":1781010536000}'),c={name:"cms/settings/cookie.md"};function g(h,t,p,u,b,m){const o=s("DocImage");return i(),l("div",null,[t[0]||(t[0]=a('<h1 id="cookie" tabindex="-1">Cookie <a class="header-anchor" href="#cookie" aria-label="Permalink to &quot;Cookie&quot;">​</a></h1><blockquote><p>Menu: <strong>Settings -&gt; Cookie Management</strong><br> Deep link: <code>/_Admin/system/cookie?SiteId={siteGuid}</code><br> Tab deep links: <code>tab=basic</code> / <code>categories</code> / <code>content</code> / <code>scripts</code> / <code>reports</code></p></blockquote><p><strong>Cookie Management</strong> configures the front-end Cookie consent banner: enable scope, display style, multilingual copy, Cookie categories, external resource classification, and consent analytics. The admin saves site-level <code>CookieConsentSetting</code>; for reading/writing individual Cookies in scripts, see <a href="/kb-docs/api/cookie/">k.cookie</a>.</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><table tabindex="0"><thead><tr><th>Action</th><th>Permission</th></tr></thead><tbody><tr><td>Open <strong>Cookie Management</strong></td><td><code>site·edit</code></td></tr><tr><td>Bottom <strong>Save</strong>, <strong>Save and preview</strong></td><td><code>site·edit</code></td></tr><tr><td>Add / edit categories, content, resources, and Cookie items</td><td><code>site·edit</code> (writes to current form; still requires bottom save)</td></tr><tr><td>Resource list multi-select <strong>Delete</strong></td><td>Page requires <code>site·edit</code>; delete button also checks <code>cookie·delete</code></td></tr></tbody></table></div><div class="warning custom-block"><p class="custom-block-title">Save behavior</p><p><strong>Save / Create</strong> in category, resource, and Cookie item dialogs only updates the current page form. Before leaving, click bottom <strong>Save</strong>; for immediate front-end check, use <strong>Save and preview</strong>—saves then opens site <a href="./basic/general.html#site-information">Base URL</a> in a new tab.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, enable <strong>Settings -&gt; Cookie Management</strong>.</li><li>Open <strong>Settings -&gt; Cookie Management</strong> in the left sidebar.</li></ol>',7)),r(o,{src:"/cms/settings/settings-cookie-overview.png",alt:"Cookie Management basic settings",width:"1120"}),t[1]||(t[1]=e("h2",{id:"page-structure",tabindex:"-1"},[n("Page Structure "),e("a",{class:"header-anchor",href:"#page-structure","aria-label":'Permalink to "Page Structure"'},"​")],-1)),t[2]||(t[2]=e("p",null,[n("Cookie Management uses tabs; switching sets URL "),e("code",null,"tab"),n(".")],-1)),r(o,{src:"/cms/settings/settings-cookie-tabs.png",alt:"Cookie Management tabs",width:"1120"}),t[3]||(t[3]=a('<table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th><th>Bottom save bar</th></tr></thead><tbody><tr><td><strong>Basic settings</strong></td><td>Enable switch, close button, reopen method, display region, Banner template</td><td>Yes</td></tr><tr><td><strong>Cookie categories</strong></td><td>Required / optional categories and default selection</td><td>Yes</td></tr><tr><td><strong>Content</strong></td><td>Multilingual consent copy, buttons, policy links</td><td>Yes</td></tr><tr><td><strong>Resource management</strong></td><td>Bind external resources to categories and list Cookies they set</td><td>Yes</td></tr><tr><td><strong>Reports</strong></td><td>Consent decisions and category trends by date</td><td>No</td></tr></tbody></table><h2 id="basic-settings" tabindex="-1">Basic Settings <a class="header-anchor" href="#basic-settings" aria-label="Permalink to &quot;Basic Settings&quot;">​</a></h2><p>Confirm basic settings last: configure categories, copy, and resources first, then enable and preview.</p>',3)),r(o,{src:"/cms/settings/settings-cookie-basic.png",alt:"Cookie basic settings",width:"1120"}),t[4]||(t[4]=a('<h3 id="enable-and-close-button" tabindex="-1">Enable and Close Button <a class="header-anchor" href="#enable-and-close-button" aria-label="Permalink to &quot;Enable and Close Button&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable Cookie management</strong></td><td>Shows consent banner on the front end; hidden when off</td></tr><tr><td><strong>Show close button</strong></td><td>Top-right close control on the banner</td></tr><tr><td><strong>Close behavior</strong></td><td>When the user closes without choosing: <strong>Accept</strong>, <strong>Reject</strong>, or <strong>Per regional law (default)</strong></td></tr></tbody></table><h3 id="panel-reopen-method" tabindex="-1">Panel Reopen Method <a class="header-anchor" href="#panel-reopen-method" aria-label="Permalink to &quot;Panel Reopen Method&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>Custom</strong></td><td>Place any element with class <code>kc-reopen-btn</code> on the front end to reopen settings</td></tr><tr><td><strong>Floating button</strong></td><td>Floating button bottom-right reopens the panel</td></tr></tbody></table><p>For ops-maintained custom button text or links, use <a href="./../content/tag-attributes.html">Tag attributes</a> or template resources rendered on the front end.</p><h3 id="display-rules" tabindex="-1">Display Rules <a class="header-anchor" href="#display-rules" aria-label="Permalink to &quot;Display Rules&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Description</th></tr></thead><tbody><tr><td><strong>All regions</strong></td><td>Show consent banner to all visitors</td></tr><tr><td><strong>EU regions</strong></td><td>Show only in EU regions</td></tr><tr><td><strong>Custom regions</strong></td><td><strong>Include</strong> or <strong>Exclude</strong> rule, then pick countries</td></tr></tbody></table><p>Country list comes from the admin API, grouped by continent.</p><h3 id="banner-template" tabindex="-1">Banner Template <a class="header-anchor" href="#banner-template" aria-label="Permalink to &quot;Banner Template&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Template</th><th>Options</th></tr></thead><tbody><tr><td><strong>Default template</strong></td><td><strong>Banner type and position</strong>; theme <strong>Light / Dark / Custom</strong>; custom theme: primary, background, text, button, button text colors</td></tr><tr><td><strong>Custom template</strong></td><td>HTML editor for full template snippet; start from system minimal template and keep required IDs and <code>data-*</code> attributes</td></tr></tbody></table><h4 id="goals-of-custom-templates" tabindex="-1">Goals of Custom Templates <a class="header-anchor" href="#goals-of-custom-templates" aria-label="Permalink to &quot;Goals of Custom Templates&quot;">​</a></h4><p>Custom templates adjust <strong>visuals, layout, copy layout, and branding</strong>: e.g. bottom banner to side panel, button order, brand copy, Cookie category layout. They do <strong>not</strong> reimplement consent logic; save state, button events, category sync, resource restore, and analytics are handled by built-in front-end scripts.</p><p>Front-end load order:</p><table tabindex="0"><thead><tr><th>Step</th><th>System behavior</th><th>Developer action</th></tr></thead><tbody><tr><td>1</td><td>Admin saves <code>CookieConsentSetting</code></td><td>Configure categories, copy, resources, template on this page</td></tr><tr><td>2</td><td>Front end requests <code>/_api/cj/client</code></td><td>System renders custom template with <a href="/kb-docs/templateEngine/">Kooboo template syntax</a></td></tr><tr><td>3</td><td>Built-in script injects template</td><td>Keep required containers, button IDs, category checkboxes</td></tr><tr><td>4</td><td>Visitor clicks accept</td><td>Built-in script writes consent Cookie, restores allowed resources, records stats</td></tr></tbody></table><h4 id="data-available-in-templates" tabindex="-1">Data Available in Templates <a class="header-anchor" href="#data-available-in-templates" aria-label="Permalink to &quot;Data Available in Templates&quot;">​</a></h4><p>Template render reads current site Cookie config:</p><table tabindex="0"><thead><tr><th>Admin area</th><th>Typical template use</th></tr></thead><tbody><tr><td><strong>Cookie categories</strong></td><td>Category name, description, required flag, default checked</td></tr><tr><td><strong>Content</strong></td><td>Title, description, intro, button labels, privacy and Cookie policy links</td></tr><tr><td><strong>Resource management</strong></td><td>Resources and Cookie items per category in details</td></tr><tr><td><strong>Basic settings</strong></td><td>Close button, floating button, banner type and position</td></tr></tbody></table><p>Avoid hardcoding business copy beyond category IDs; multilingual sites should use <strong>Content</strong> and <strong>Cookie categories</strong> multilingual fields.</p><h4 id="required-dom-conventions" tabindex="-1">Required DOM Conventions <a class="header-anchor" href="#required-dom-conventions" aria-label="Permalink to &quot;Required DOM Conventions&quot;">​</a></h4><p>Built-in scripts bind by these IDs/attributes. You may change tags, hierarchy, and styles, but keep these identifiers unique.</p><table tabindex="0"><thead><tr><th>Identifier</th><th>Role</th></tr></thead><tbody><tr><td><code>kb-cookie-banner</code></td><td>Banner container; show/hide</td></tr><tr><td><code>kb-cookie-accept-all</code></td><td>Banner <strong>Accept all</strong></td></tr><tr><td><code>kb-cookie-save</code></td><td>Banner <strong>Save selection</strong></td></tr><tr><td><code>kb-cookie-reject</code></td><td>Banner <strong>Reject non-essential</strong></td></tr><tr><td><code>kb-cookie-settings</code></td><td>Open settings modal from banner</td></tr><tr><td><code>kb-cookie-close</code></td><td>Banner close; behavior from <strong>Close behavior</strong></td></tr><tr><td><code>kb-cookie-modal</code></td><td>Settings modal container</td></tr><tr><td><code>kb-cookie-modal-overlay</code></td><td>Modal overlay</td></tr><tr><td><code>kb-cookie-modal-close</code></td><td>Close settings modal</td></tr><tr><td><code>kb-cookie-modal-accept-all</code></td><td>Modal <strong>Accept all</strong></td></tr><tr><td><code>kb-cookie-modal-save</code></td><td>Modal <strong>Save selection</strong></td></tr><tr><td><code>kb-cookie-modal-reject</code></td><td>Modal <strong>Reject non-essential</strong></td></tr><tr><td><code>data-category-id=&quot;{categoryId}&quot;</code></td><td>Category checkbox; sync and read visitor choice</td></tr><tr><td><code>data-tab</code> / <code>data-tab-content</code></td><td>Tab switch inside settings modal</td></tr><tr><td><code>data-expand-category</code> / <code>data-resources-category</code></td><td>Expand category details and resource list</td></tr><tr><td><code>kc-reopen-btn</code></td><td>Custom reopen button class when not using floating button</td></tr></tbody></table><p>For light branding, change CSS, copy layout, and button order first; if restructuring DOM, keep all identifiers above and verify step by step.</p><h4 id="behaviors-handled-by-built-in-scripts" tabindex="-1">Behaviors Handled by Built-in Scripts <a class="header-anchor" href="#behaviors-handled-by-built-in-scripts" aria-label="Permalink to &quot;Behaviors Handled by Built-in Scripts&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Behavior</th><th>Description</th></tr></thead><tbody><tr><td>First visit display</td><td>Per <code>typeAndPosition</code>: banner, modal, or inline</td></tr><tr><td>Category checkbox sync</td><td>Same category in banner and modal syncs via <code>data-category-id</code></td></tr><tr><td>Required category protection</td><td>Required categories stay on; visitors cannot uncheck</td></tr><tr><td>Consent persistence</td><td>Writes <code>kb_cookie_consent</code>; later visits respect saved state</td></tr><tr><td>Resource restore</td><td><code>kc-src</code> / <code>kc-href</code> revert to real <code>src</code> / <code>href</code> after category consent</td></tr><tr><td>Iframe placeholder</td><td><strong>Iframe placeholder content</strong> until consent; then original URL</td></tr><tr><td>Analytics</td><td>Consent results feed <strong>Reports</strong></td></tr></tbody></table><p>Custom templates should not write consent Cookies themselves, load blocked third parties, or bypass <a href="#resource-management">Resource management</a> categories.</p><h4 id="development-checklist" tabindex="-1">Development Checklist <a class="header-anchor" href="#development-checklist" aria-label="Permalink to &quot;Development Checklist&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Check</th><th>Description</th></tr></thead><tbody><tr><td>Button IDs</td><td>Accept all, save, reject, settings, close all work</td></tr><tr><td>Category checkboxes</td><td>Each optional category has <code>data-category-id</code>; required categories cannot be unchecked</td></tr><tr><td>Reopen entry</td><td>Floating button or <code>kc-reopen-btn</code> present</td></tr><tr><td>Mobile</td><td>Banner, modal, buttons usable on small screens</td></tr><tr><td>Resource restore</td><td>Third parties blocked on reject; restore after consent</td></tr><tr><td>Multilingual</td><td>Title, buttons, categories, policy links per site language</td></tr></tbody></table><h2 id="cookie-categories" tabindex="-1">Cookie Categories <a class="header-anchor" href="#cookie-categories" aria-label="Permalink to &quot;Cookie Categories&quot;">​</a></h2><p>Categories define what visitors can choose; used by resource management and reports.</p>',29)),r(o,{src:"/cms/settings/settings-cookie-categories.png",alt:"Cookie categories",width:"1120"}),t[5]||(t[5]=a('<table tabindex="0"><thead><tr><th>Area</th><th>Description</th></tr></thead><tbody><tr><td><strong>Add category</strong></td><td>Dialog; name and description per supported language</td></tr><tr><td><strong>Language selector</strong></td><td>Edit language; list from site multilingual config</td></tr><tr><td><strong>Category cards</strong></td><td>Required first, optional after</td></tr><tr><td><strong>Required / Optional</strong></td><td>Required cannot be unchecked by default; optional can be deleted</td></tr><tr><td><strong>Default selected</strong></td><td>Pre-checked on first open; required always selected</td></tr></tbody></table>',1)),r(o,{src:"/cms/settings/settings-cookie-add-category-dialog.png",alt:"Add Cookie category",width:"1120"}),t[6]||(t[6]=e("p",null,[n("New categories default to "),e("strong",null,"optional"),n(", not pre-selected. Still in form until bottom "),e("strong",null,"Save"),n(".")],-1)),t[7]||(t[7]=e("h2",{id:"content",tabindex:"-1"},[n("Content "),e("a",{class:"header-anchor",href:"#content","aria-label":'Permalink to "Content"'},"​")],-1)),t[8]||(t[8]=e("p",null,"Copy visitors see. For multilingual sites, check each language.",-1)),r(o,{src:"/cms/settings/settings-cookie-content.png",alt:"Cookie content configuration",width:"1120"}),t[9]||(t[9]=a('<table tabindex="0"><thead><tr><th>Field</th><th>Where shown</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Consent dialog title</td></tr><tr><td><strong>Description</strong></td><td>Main explanation</td></tr><tr><td><strong>Introduction</strong></td><td>Settings panel intro</td></tr><tr><td><strong>Accept all</strong></td><td>Accept all Cookies button</td></tr><tr><td><strong>Accept selected</strong></td><td>Save current category selection</td></tr><tr><td><strong>Reject all</strong></td><td>Reject non-essential Cookies</td></tr><tr><td><strong>Privacy policy link</strong></td><td>Privacy policy URL and link text</td></tr><tr><td><strong>Cookie policy link</strong></td><td>Cookie policy URL and link text</td></tr><tr><td><strong>Iframe placeholder content</strong></td><td>HTML shown in iframe until category consent</td></tr></tbody></table><h2 id="resource-management" tabindex="-1">Resource Management <a class="header-anchor" href="#resource-management" aria-label="Permalink to &quot;Resource Management&quot;">​</a></h2><p>Tells the system which external <code>script</code>, <code>img</code>, <code>iframe</code>, or <code>link</code> belongs to which category and which Cookies it may set.</p>',3)),r(o,{src:"/cms/settings/settings-cookie-scripts.png",alt:"Cookie resource management",width:"1120"}),t[10]||(t[10]=a('<h3 id="resource-list" tabindex="-1">Resource List <a class="header-anchor" href="#resource-list" aria-label="Permalink to &quot;Resource List&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column / action</th><th>Description</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>External resource address</td></tr><tr><td><strong>Category</strong></td><td>Cookie category</td></tr><tr><td><strong>Expand row</strong></td><td>Cookies for resource; <strong>Add Cookie</strong>, edit, delete</td></tr><tr><td><strong>Edit</strong></td><td>URL, type, category, Cookie list</td></tr><tr><td><strong>Delete / multi-delete</strong></td><td>Remove from config; still requires bottom save</td></tr></tbody></table><h3 id="add-resource" tabindex="-1">Add Resource <a class="header-anchor" href="#add-resource" aria-label="Permalink to &quot;Add Resource&quot;">​</a></h3>',3)),r(o,{src:"/cms/settings/settings-cookie-add-resource-dialog.png",alt:"Add Cookie resource",width:"1120"}),t[11]||(t[11]=a('<table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>Pick from site pages, layouts, views, HTML blocks, or type manually</td></tr><tr><td><strong>Resource type</strong></td><td><code>script</code>, <code>img</code>, <code>iframe</code>, <code>link</code>; UI labels Script, Image, Iframe, Link; auto-filled when picking URL</td></tr><tr><td><strong>Analyze</strong></td><td>Backend analyzes Cookies; merges into list without duplicates</td></tr><tr><td><strong>Category</strong></td><td>Required; from <a href="#cookie-categories">Cookie categories</a></td></tr><tr><td><strong>Cookie list</strong></td><td>Name, description, expiry per Cookie</td></tr></tbody></table><p>Cookie item fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Cookie name</strong></td><td>Required; actual browser Cookie name</td></tr><tr><td><strong>Description</strong></td><td>Multilingual purpose for visitors</td></tr><tr><td><strong>Expiry</strong></td><td>Minutes; e.g. <code>60</code> = 1 hour, <code>1440</code> = 1 day</td></tr></tbody></table><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h2><p>Read-only; no bottom save. Pick date range after opening tab:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Description</th></tr></thead><tbody><tr><td><strong>Decision trend</strong></td><td><strong>Accept all</strong>, <strong>Reject all</strong>, <strong>Custom selection</strong></td></tr><tr><td><strong>Category trend</strong></td><td>Consent per category; names in current language</td></tr></tbody></table><p>Default range: last 7 days. Empty state if no data; from actual visitor consent submissions.</p><h2 id="typical-workflow" tabindex="-1">Typical Workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical Workflow&quot;">​</a></h2><ol><li>Confirm <a href="./basic/general.html#site-information">Base URL</a> and <a href="./basic/general.html#multilingual">multilingual</a>.</li><li>Maintain required and optional categories under <strong>Cookie categories</strong>.</li><li>Fill title, copy, buttons, policy links per language under <strong>Content</strong>.</li><li>Add external scripts, iframes, images, or links under <strong>Resource management</strong> with categories.</li><li>Under <strong>Basic settings</strong>, pick region, reopen method, Banner template; enable Cookie management.</li><li><strong>Save and preview</strong>; test first visit, reject, accept selected, reopen in incognito or after clearing Cookies.</li><li>Review <strong>Reports</strong> after go-live.</li></ol><h2 id="cms-vs-api-template-engine" tabindex="-1">CMS vs API / Template Engine <a class="header-anchor" href="#cms-vs-api-template-engine" aria-label="Permalink to &quot;CMS vs API / Template Engine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>CMS</th><th>API / Template Engine</th></tr></thead><tbody><tr><td>Consent banner, categories, copy, resource mapping</td><td>This page</td><td>—</td></tr><tr><td>Read/set/delete browser Cookies in KScript</td><td>Admin config only</td><td><a href="/kb-docs/api/cookie/">k.cookie</a></td></tr><tr><td>Request Cookies in template data flow</td><td>Not expanded in admin</td><td><a href="/kb-docs/templateEngine/k-data/tags.html#let">k-data tag syntax</a></td></tr><tr><td>Custom reopen button on front end</td><td><code>kc-reopen-btn</code> on this page</td><td><a href="./../content/tag-attributes.html">Tag attributes</a>, template resources</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./">Settings overview</a></td><td>Settings menu and suggested order</td></tr><tr><td><a href="./basic/">Basic Settings</a></td><td>Base URL, multilingual, site switches</td></tr><tr><td><a href="./domains.html">Domains</a></td><td>Multi-domain and language binding</td></tr><tr><td><a href="/kb-docs/api/cookie/">k.cookie</a></td><td>KScript Cookie read/write</td></tr><tr><td><a href="/kb-docs/templateEngine/k-data/tags.html">k-data tag syntax</a></td><td>Read values from Cookies in templates</td></tr></tbody></table>',13))])}const f=d(c,[["render",g]]);export{y as __pageData,f as default};
